import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.C1oW5ckO.js";var c=JSON.parse(`{"title":"Sign PumpkinMC Plugins","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/actions/sign-pumpkin-plugin/docs/index.md"},"headers":[],"relativePath":"actions/sign-pumpkin-plugin/docs/index.md","filePath":"actions/sign-pumpkin-plugin/docs/index.md","lastUpdated":1792029797000}`),l={name:`actions/sign-pumpkin-plugin/docs/index.md`},u={id:`sign-pumpkinmc-plugins`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/sign-pumpkin-plugin-v0.0.4`,"aria-label":`Release v0.0.4`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`span`,{class:`component-page-title__text`},[t(`Sign PumpkinMC Plugins `),n(`a`,{class:`header-anchor`,href:`#sign-pumpkinmc-plugins`,"aria-label":`Permalink to “Sign PumpkinMC Plugins”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.0.4`})])]),c[1]||=r(`<p>The signing action adds Pumpkin&#39;s Ed25519 signature and release metadata to one or more existing plugin <code>.wasm</code> files. It signs in place and does not build them. Run it on the exact artifact from the build job, before publishing or distributing that artifact.</p><p>For a workflow example and the complete input list, see the <a href="./../README">action README</a>.</p><p>For one file, provide the plugin name, version without a leading <code>v</code>, and wasm path. For a release with several plugins, use <code>plugins-manifest</code>, a JSON array of those three values; the developer name and key apply to every item. The action replaces existing signing sections, verifies the result before writing, and refreshes an adjacent <code>.sha256</code> file when one exists.</p><p>Store the 32-byte Ed25519 seed as 64 hexadecimal characters in a protected GitHub secret. Set <code>warn: true</code> only when a missing key should intentionally leave files unsigned, such as a fork workflow. Malformed keys, missing files, and failed verification remain errors. See <a href="../action.yml">action.yml</a> for the runtime and entry point; no setup step is needed.</p>`,4)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};